function ensureColumn(table:string,column:string,type:string){const columns=db.prepare(`PRAGMA table_info(${table})`).all() as any[];if(!columns.some(c=>c.name===column))db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${type}`);}
