const app:Express=express();app.use(cors());app.use(express.json());const clients=new Set<express.Response>();const now=()=>new Date().toISOString();const promptHash=(value:string)=>createHash('sha256').update(value).digest('hex');const locks=new WorkspaceLockManager();const running=new Map<string,AbortController>();const isolation=new TaskIsolationManager();
function safePlanningError(error:unknown){const message=String((error as any)?.message||error).replace(/\s+/g,' ').trim();return (message||'Não foi possível gerar o plano.').slice(0,500);}
function persistBrowserQaArtifact(task:any,executionId:string,structuredResult:any,createdAt:string){const qa=structuredResult?.browserQa;if(!qa)return;const report={status:qa.status,baseUrl:qa.baseUrl,routes:qa.routes||[],consoleErrors:qa.consoleErrors||[],pageErrors:qa.pageErrors||[],failedRequests:qa.failedRequests||[],screenshots:(qa.screenshots||[]).map((item:any)=>({filename:item.filename,route:item.route,path:item.path})),summary:qa.summary||'',durationMs:qa.durationMs||0};db.prepare('INSERT INTO artifacts VALUES (?,?,?,?,?,?,?)').run(nanoid(),task.id,executionId,'browser_qa_report','Browser QA report',JSON.stringify(report),createdAt);}
const CONFIG_ROLES:AgentRole[]=['planner','developer','tester','reviewer'];type ConfigOrigin='workspace'|'global'|'environment'|'default';
function persistedConfigs(workspaceId:string|null){const rows:any[]=db.prepare('SELECT role,provider,model FROM agent_configs WHERE workspaceId IS ?').all(workspaceId);return Object.fromEntries(rows.map(row=>[row.role,{provider:row.provider,model:row.model}]));}
type ExecutionPolicyOrigin='global'|'workspace'|'environment'|'default';
const EXECUTION_POLICY_KEYS:(keyof ExecutionPolicy)[]=['autoFixEnabled','maxFixCycles','testerRequired','browserQaEnabled','browserQaRequired'];
function persistedExecutionPolicy(workspaceId:string|null){const row:any=db.prepare('SELECT autoFixEnabled,maxFixCycles,testerRequired,browserQaEnabled,browserQaRequired FROM execution_policies WHERE workspaceId IS ? ORDER BY updatedAt DESC LIMIT 1').get(workspaceId);return row?{autoFixEnabled:Boolean(row.autoFixEnabled),maxFixCycles:Number(row.maxFixCycles),testerRequired:Boolean(row.testerRequired),browserQaEnabled:Boolean(row.browserQaEnabled),browserQaRequired:Boolean(row.browserQaRequired)}:{};}
function environmentExecutionPolicy():Partial<ExecutionPolicy>{const value:Partial<ExecutionPolicy>={};if(process.env.AUTO_FIX_ENABLED!==undefined)value.autoFixEnabled=String(process.env.AUTO_FIX_ENABLED).toLowerCase()!=='false';if(process.env.MAX_FIX_CYCLES!==undefined){const parsed=Number(process.env.MAX_FIX_CYCLES);if(Number.isFinite(parsed)&&parsed>=0)value.maxFixCycles=Math.floor(parsed);}if(process.env.TESTER_REQUIRED!==undefined)value.testerRequired=String(process.env.TESTER_REQUIRED).toLowerCase()==='true';if(process.env.BROWSER_QA_ENABLED!==undefined)value.browserQaEnabled=String(process.env.BROWSER_QA_ENABLED).toLowerCase()==='true';if(process.env.BROWSER_QA_REQUIRED!==undefined)value.browserQaRequired=String(process.env.BROWSER_QA_REQUIRED).toLowerCase()==='true';return value;}
function normalizeExecutionPolicy(payload:any):ExecutionPolicy{if(!payload||typeof payload!=='object')throw Object.assign(new Error('Execution policy object is required'),{status:400});const max=Number(payload.maxFixCycles);if(!Number.isInteger(max)||max<0||max>100)throw Object.assign(new Error('maxFixCycles must be an integer between 0 and 100'),{status:400});if(typeof payload.autoFixEnabled!=='boolean'||typeof payload.testerRequired!=='boolean')throw Object.assign(new Error('Execution policy fields must be boolean'),{status:400});const browserQaEnabled=payload.browserQaEnabled??false,browserQaRequired=payload.browserQaRequired??false;if(typeof browserQaEnabled!=='boolean'||typeof browserQaRequired!=='boolean')throw Object.assign(new Error('Browser QA policy fields must be boolean'),{status:400});if(browserQaRequired&&!browserQaEnabled)throw Object.assign(new Error('browserQaRequired requires browserQaEnabled'),{status:400});return{autoFixEnabled:payload.autoFixEnabled,maxFixCycles:max,testerRequired:payload.testerRequired,browserQaEnabled,browserQaRequired};}
function effectiveExecutionPolicy(workspaceId?:string){const global=persistedExecutionPolicy(null),workspace=workspaceId?persistedExecutionPolicy(workspaceId):{},environment=environmentExecutionPolicy();const values:any={};const origins:any={};for(const key of EXECUTION_POLICY_KEYS){if(workspace[key]!==undefined){values[key]=workspace[key]!;origins[key]='workspace';}else if(global[key]!==undefined){values[key]=global[key]!;origins[key]='global';}else if(environment[key]!==undefined){values[key]=environment[key]!;origins[key]='environment';}else{values[key]=DEFAULT_EXECUTION_POLICY[key];origins[key]='default';}}return{values,origins,global,workspace};}
function ensureGlobalExecutionPolicy(){if(Object.keys(persistedExecutionPolicy(null)).length)return;const env=environmentExecutionPolicy();const value:ExecutionPolicy={autoFixEnabled:env.autoFixEnabled??DEFAULT_EXECUTION_POLICY.autoFixEnabled,maxFixCycles:env.maxFixCycles??DEFAULT_EXECUTION_POLICY.maxFixCycles,testerRequired:env.testerRequired??DEFAULT_EXECUTION_POLICY.testerRequired,browserQaEnabled:env.browserQaEnabled??DEFAULT_EXECUTION_POLICY.browserQaEnabled,browserQaRequired:env.browserQaRequired??DEFAULT_EXECUTION_POLICY.browserQaRequired};db.prepare('INSERT INTO execution_policies (id,workspaceId,autoFixEnabled,maxFixCycles,testerRequired,browserQaEnabled,browserQaRequired,config,updatedAt) VALUES (?,?,?,?,?,?,?,?,?)').run(nanoid(),null,value.autoFixEnabled?1:0,value.maxFixCycles,value.testerRequired?1:0,value.browserQaEnabled?1:0,value.browserQaRequired?1:0,JSON.stringify({source:Object.keys(env).length?'environment':'default'}),now());}
function saveExecutionPolicy(workspaceId:string|null,payload:any){const value=normalizeExecutionPolicy(payload);db.prepare('DELETE FROM execution_policies WHERE workspaceId IS ?').run(workspaceId);db.prepare('INSERT INTO execution_policies (id,workspaceId,autoFixEnabled,maxFixCycles,testerRequired,browserQaEnabled,browserQaRequired,config,updatedAt) VALUES (?,?,?,?,?,?,?,?,?)').run(nanoid(),workspaceId,value.autoFixEnabled?1:0,value.maxFixCycles,value.testerRequired?1:0,value.browserQaEnabled?1:0,value.browserQaRequired?1:0,JSON.stringify({source:workspaceId?'workspace':'global'}),now());audit('execution_policy.updated',{workspaceId:workspaceId||null,autoFixEnabled:value.autoFixEnabled,maxFixCycles:value.maxFixCycles,testerRequired:value.testerRequired,browserQaEnabled:value.browserQaEnabled,browserQaRequired:value.browserQaRequired});emit('execution_policy.updated',{workspaceId:workspaceId||null});}
function executionPolicyResponse(workspaceId:string|null){const effective=effectiveExecutionPolicy(workspaceId||undefined);return{global:effective.global,effective:effective.values,origins:effective.origins,...(workspaceId?{workspace:effective.workspace}: {})};}
function environmentConfigs(){const configs=buildAgentConfigs(CONFIG_ROLES,{reviewerProvider:process.env.REVIEWER_PROVIDER,codexModel:process.env.CODEX_MODEL,developerProvider:process.env.DEVELOPER_PROVIDER,claudeModel:process.env.CLAUDE_MODEL,testerProvider:process.env.TESTER_PROVIDER});return Object.fromEntries(configs.map(config=>[config.role,{provider:config.provider,model:config.model}]));}
function effectiveConfigs(workspaceId?:string){const global=persistedConfigs(null);const workspace=workspaceId?persistedConfigs(workspaceId):{};const environment=environmentConfigs();const values:any={};const origins:any={};for(const role of CONFIG_ROLES){if(workspace[role]){values[role]=workspace[role];origins[role]='workspace';}else if(global[role]){values[role]=global[role];origins[role]='global';}else{values[role]=environment[role];origins[role]=environment[role]?.provider==='mock'?'default':'environment';}}return{values,origins};}
type MissionPlannerProvider='mock'|'claude-code';type MissionPlannerOrigin='workspace'|'global'|'environment'|'default';type MissionPlannerConfig={provider:MissionPlannerProvider;model:string;origin:MissionPlannerOrigin};
function persistedMissionPlannerConfig(workspaceId:string|null){const row:any=db.prepare('SELECT provider,model,config FROM mission_planner_configs WHERE workspaceId IS ? LIMIT 1').get(workspaceId);if(!row)return undefined;let metadata:any={};try{metadata=JSON.parse(row.config||'{}')}catch{}return{provider:String(row.provider),model:String(row.model),source:metadata.source};}
function resolveMissionPlannerConfig(workspaceId:string):MissionPlannerConfig{const workspace=persistedMissionPlannerConfig(workspaceId);if(workspace)return{provider:workspace.provider as MissionPlannerProvider,model:workspace.model,origin:'workspace'};const global=persistedMissionPlannerConfig(null);if(global&&global.source!=='bootstrap')return{provider:global.provider as MissionPlannerProvider,model:global.model,origin:'global'};const provider=process.env.MISSION_PLANNER_PROVIDER||'mock';const model=process.env.MISSION_PLANNER_MODEL||(provider==='claude-code'?'sonnet':'mock-reasoning');return{provider:provider as MissionPlannerProvider,model,origin:(process.env.MISSION_PLANNER_PROVIDER||process.env.MISSION_PLANNER_MODEL)?'environment':'default'};}
function createMissionPlanner(config:MissionPlannerConfig):MissionPlanner{if(config.provider==='mock')return new MockMissionPlanner();if(config.provider==='claude-code')return new AdapterClaudeCodeMissionPlanner({model:config.model}) as unknown as MissionPlanner;throw Object.assign(new Error(`Unknown Mission Planner provider: ${config.provider}`),{kind:'configuration_error',code:'configuration_error'});}
function ensureGlobalProviderConfig(){const environment=environmentConfigs();const insert=db.prepare('INSERT INTO agent_configs (id,workspaceId,role,provider,model,config) VALUES (?,?,?,?,?,?)');for(const role of CONFIG_ROLES){if(db.prepare('SELECT 1 FROM agent_configs WHERE workspaceId IS NULL AND role=? LIMIT 1').get(role))continue;const envKey=role==='developer'?'DEVELOPER_PROVIDER':role==='reviewer'?'REVIEWER_PROVIDER':role==='tester'?'TESTER_PROVIDER':'';const value=envKey&&process.env[envKey]?environment[role]:DEFAULT_PROVIDER_CONFIG[role]!;insert.run(nanoid(),null,role,value.provider,value.model,JSON.stringify({source:'bootstrap'}));}}
function migratePersistedProviderConfig(){const rows:any[]=db.prepare('SELECT id,role,provider,model FROM agent_configs').all();for(const row of rows){if(!CONFIG_ROLES.includes(row.role))continue;const role=row.role as AgentRole;const fallback=DEFAULT_PROVIDER_CONFIG[role]!;if(!modelForProvider(row.provider,row.model)&&modelForProvider(row.provider,fallback.model))db.prepare('UPDATE agent_configs SET model=?,config=? WHERE id=?').run(fallback.model,JSON.stringify({source:'migration',reason:'invalid_or_empty_model'}),row.id);}}
ensureGlobalProviderConfig();migratePersistedProviderConfig();ensureGlobalExecutionPolicy();
function providerHealthRow(providerId:string){return db.prepare('SELECT * FROM provider_health WHERE providerId=?').get(providerId) as any;}
function normalizeProviderHealth(){const update=db.prepare('UPDATE provider_health SET authenticated=0,authMode=?,authenticationStatus=? WHERE providerId=?');for(const entry of PROVIDER_REGISTRY){const semantics=providerAuthSemantics(entry.id);update.run(semantics.authMode,semantics.authenticationStatus,entry.id);}}
normalizeProviderHealth();
async function refreshProviderHealth(){const rows:any[]=[];for(const entry of PROVIDER_REGISTRY){const started=Date.now();let available=true;let authenticated=false;let error=null;let version=null;let resolvedExecutable=null;let supportedExecFlags:string[]=[];try{if(entry.id==='claude-code'){const adapter=new ClaudeCodeAdapter();available=await adapter.checkAvailability();const health:any=await adapter.getHealth();authenticated=Boolean(health.authenticated??available);error=health.error||null;version=health.version||null;resolvedExecutable=health.resolvedExecutable||null;supportedExecFlags=health.supportedExecFlags||[];}else if(entry.id==='codex-cli'){const adapter=new CodexCliAdapter();available=await adapter.checkAvailability();const health:any=await adapter.getHealth();authenticated=Boolean(health.authenticated??available);error=health.error||null;version=health.version||null;resolvedExecutable=health.resolvedExecutable||null;supportedExecFlags=health.supportedExecFlags||[];}}catch(exception){available=false;error=String(exception);}const checkedAt=now();db.prepare('INSERT INTO provider_health (providerId,available,authenticated,lastCheckAt,latencyMs,error,authenticationStatus,authMode,billingMode,version,resolvedExecutable,supportedExecFlags) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(providerId) DO UPDATE SET available=excluded.available,authenticated=excluded.authenticated,lastCheckAt=excluded.lastCheckAt,latencyMs=excluded.latencyMs,error=excluded.error,authenticationStatus=excluded.authenticationStatus,authMode=excluded.authMode,billingMode=excluded.billingMode,version=excluded.version,resolvedExecutable=excluded.resolvedExecutable,supportedExecFlags=excluded.supportedExecFlags').run(entry.id,available?1:0,0,checkedAt,Date.now()-started,error,providerAuthSemantics(entry.id).authenticationStatus,providerAuthSemantics(entry.id).authMode,entry.billingMode,version,resolvedExecutable,JSON.stringify(supportedExecFlags));const row=providerHealthRow(entry.id);rows.push({...row,available:Boolean(row.available),authenticated:Boolean(row.authenticated),supportedExecFlags:JSON.parse(row.supportedExecFlags||'[]')});emit('provider.health.updated',{providerId:entry.id,available:available,authenticated});}return rows;}
function providerCatalog(){normalizeProviderHealth();return PROVIDER_REGISTRY.map(entry=>{const health=providerHealthRow(entry.id);const models:any[]=db.prepare('SELECT * FROM model_catalog WHERE providerId=? AND enabled=1').all(entry.id).map((row:any)=>({...row,capabilities:JSON.parse(row.capabilities),metadata:JSON.parse(row.metadata),contextWindow:row.contextWindow||null,inputCostPerMillion:row.inputCostPerMillion||null,outputCostPerMillion:row.outputCostPerMillion||null}));const semantics=providerAuthSemantics(entry.id);return{...entry,authMode:semantics.authMode,health:health?{...health,available:Boolean(health.available),authenticated:Boolean(health.authenticated),supportedExecFlags:JSON.parse(health.supportedExecFlags||'[]')}:null,models};});}
function validateConfigPayload(payload:any){if(!payload||typeof payload!=='object')return 'Configuration object is required';for(const role of CONFIG_ROLES){const config=payload[role];if(!config)return `Missing configuration for ${role}`;const result=validateAgentConfig(role,String(config.provider),String(config.model));if(!result.valid)return result.error;}return null;}
function workspaceProviderConfigResponse(workspaceId:string){const effective=effectiveConfigs(workspaceId);return{global:persistedConfigs(null),workspace:persistedConfigs(workspaceId),effective:effective.values,origins:effective.origins};}
function saveProviderConfig(workspaceId:string|null,payload:any){const error=validateConfigPayload(payload);if(error)throw Object.assign(new Error(error),{status:400});const tx=db.transaction(()=>{db.prepare('DELETE FROM agent_configs WHERE workspaceId IS ?').run(workspaceId);const insert=db.prepare('INSERT INTO agent_configs (id,workspaceId,role,provider,model,config) VALUES (?,?,?,?,?,?)');for(const role of CONFIG_ROLES){const config=payload[role];insert.run(nanoid(),workspaceId,role,config.provider,config.model,JSON.stringify({source:workspaceId?'workspace':'global'}));}});tx();audit('provider.config.updated',{workspaceId:workspaceId||null,roles:CONFIG_ROLES});emit('provider.config.updated',{workspaceId:workspaceId||null});}
