function saveMissionPlannerConfig(workspaceId:string|null,payload:any){const provider=String(payload?.provider||''),model=String(payload?.model||'');if(!['mock','claude-code'].includes(provider)||!model)throw Object.assign(new Error('Mission Planner provider/model inválidos'),{status:400});if(provider==='mock'&&!['mock-reasoning','mock-fast'].includes(model))throw Object.assign(new Error('Modelo Mock inválido'),{status:400});if(provider==='claude-code'&&!['sonnet','haiku'].includes(model))throw Object.assign(new Error('Modelo Claude Code inválido'),{status:400});db.prepare('DELETE FROM mission_planner_configs WHERE workspaceId IS ?').run(workspaceId);db.prepare('INSERT INTO mission_planner_configs (id,workspaceId,provider,model,config,updatedAt) VALUES (?,?,?,?,?,?)').run(nanoid(),workspaceId,provider,model,JSON.stringify({source:workspaceId?'workspace':'global'}),now());audit('mission_planner.config.updated',{workspaceId:workspaceId||null,provider,model});}
