function resolveMissionChildTask(missionId:string,missionTask:any){let task:any=missionTask.taskId?db.prepare('SELECT * FROM tasks WHERE id=?').get(missionTask.taskId):null;if(!task)task=db.prepare('SELECT * FROM tasks WHERE missionId=? AND missionTaskId=? ORDER BY createdAt DESC LIMIT 1').get(missionId,missionTask.id);if(task&&missionTask.taskId!==task.id)db.prepare('UPDATE mission_tasks SET taskId=?,updatedAt=? WHERE id=?').run(task.id,now(),missionTask.id);return task;}function repairMissionChildTaskLinks(){const rows:any[]=db.prepare('SELECT * FROM mission_tasks WHERE taskId IS NULL').all();for(const row of rows){const matches:any[]=db.prepare('SELECT id FROM tasks WHERE missionId=? AND missionTaskId=? ORDER BY createdAt DESC').all(row.missionId,row.id);if(matches.length===1)db.prepare('UPDATE mission_tasks SET taskId=?,updatedAt=? WHERE id=?').run(matches[0].id,now(),row.id);else if(matches.length>1)audit('mission.child_task_link_ambiguous',{missionId:row.missionId,missionTaskId:row.id,candidates:matches.map(item=>item.id)});}}repairMissionChildTaskLinks();async function runMissionFixed(missionId:string){if(runningMissions.has(missionId))return;runningMissions.add(missionId);try{for(;;){const detail=missionDetail(missionId);if(!detail)return;const current=detail.tasks.find((item:any)=>item.status==='failed')||detail.tasks.find((item:any)=>item.status==='blocked')||detail.tasks.find((item:any)=>item.status==='running')||detail.tasks.find((item:any)=>item.status==='approved')||detail.tasks.find((item:any)=>item.status==='planned');if(!current){db.prepare('UPDATE missions SET status=?,completedAt=?,environmentStatus=?,updatedAt=? WHERE id=?').run('completed',now(),'approved_waiting_action',now(),missionId);emit('mission.completed',{missionId},undefined,undefined);return;}const dependencyIds=current.dependsOn||[];const dependencies=detail.tasks.filter((item:any)=>dependencyIds.includes(item.id));if(dependencies.some((item:any)=>item.status!=='completed')){db.prepare('UPDATE missions SET status=?,updatedAt=? WHERE id=?').run('waiting_human',now(),missionId);return;}let task:any=resolveMissionChildTask(missionId,current);if(!task&&['failed','blocked'].includes(current.status)){db.prepare('UPDATE missions SET status=?,environmentWarning=?,updatedAt=? WHERE id=?').run('waiting_human','A etapa parada não possui child task vinculada.',now(),missionId);audit('mission.child_task_missing',{missionId,missionTaskId:current.id,status:current.status});return;}if(!task){const id=nanoid(),t=now(),workspace:any=detail.workspace;const snapshot=detail.mission.configSnapshot||JSON.stringify({pipeline:DEFAULT_PIPELINE,agentConfigs:[],missionPlanner:{provider:detail.mission.missionPlannerProvider,model:detail.mission.missionPlannerModel}});db.prepare('INSERT INTO tasks (id,workspaceId,title,description,pipeline,status,currentStage,lastSuccessfulStage,resumable,taskBudgetUsd,tokenBudget,configSnapshot,createdAt,updatedAt,isolationMode,baseBranch,baseCommitSha,taskBranch,worktreePath,environmentStatus,missionId,missionTaskId,projectContextVersion,projectContextSourceCommitSha,projectContextSnapshot,projectContextStatus) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(id,workspace.id,current.title,[current.description,'Critérios de aceite:',...(current.acceptanceCriteria||[]),'Contexto da missão:',detail.mission.request].join('\n'),JSON.stringify(DEFAULT_PIPELINE),'pending',null,null,1,0,0,snapshot,t,t,'worktree',detail.mission.baseBranch,detail.mission.baseCommitSha,detail.mission.missionBranch,detail.mission.worktreePath,'active',missionId,current.id,detail.mission.projectContextVersion,detail.mission.projectContextSourceCommitSha,detail.mission.projectContextSnapshot,detail.mission.projectContextStatus||'not_analyzed');task=db.prepare('SELECT * FROM tasks WHERE id=?').get(id);}db.prepare('UPDATE mission_tasks SET taskId=?,status=?,updatedAt=? WHERE id=?').run(task.id,'running',now(),current.id);await runTask(task);const latest:any=db.prepare('SELECT status FROM tasks WHERE id=?').get(task.id);if(latest?.status==='approved'){db.prepare('UPDATE mission_tasks SET status=?,updatedAt=? WHERE id=?').run('completed',now(),current.id);continue;}db.prepare('UPDATE mission_tasks SET status=?,updatedAt=? WHERE id=?').run(latest?.status==='failed'?'failed':'blocked',now(),current.id);db.prepare('UPDATE missions SET status=?,updatedAt=? WHERE id=?').run('waiting_human',now(),missionId);return;}}finally{runningMissions.delete(missionId);}}
