app.post('/api/missions/:id/resume',(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);if(mission.status!=='waiting_human')return res.status(409).json({error:'A missão não está aguardando intervenção.'});if(runningMissions.has(mission.id))return res.status(409).json({error:'A missão já está em execução.'});const target:any=db.prepare("SELECT * FROM mission_tasks WHERE missionId=? ORDER BY CASE status WHEN 'failed' THEN 0 WHEN 'blocked' THEN 1 WHEN 'running' THEN 2 ELSE 3 END, position LIMIT 1").get(mission.id);if(!target)return res.status(409).json({code:'mission_resume_blocked',error:'Nenhuma etapa parada com child task encontrada.'});const task:any=db.prepare('SELECT * FROM tasks WHERE id=?').get(target.taskId);if(!task)return res.status(409).json({code:'mission_resume_blocked',error:'A child task da etapa não foi encontrada.'});const events:any[]=db.prepare('SELECT type,payload FROM events WHERE taskId=? ORDER BY createdAt').all(task.id).map((e:any)=>({type:e.type,payload:JSON.parse(e.payload)}));const budgetPayload=[...events].reverse().find((e:any)=>e.type==='budget.exceeded')?.payload;const workspacePayload=[...events].reverse().find((e:any)=>e.type==='workspace.token_limit_exceeded')?.payload;const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(task.workspaceId);const resumeControl=resumeControlForTask(task,budgetPayload?.data??budgetPayload??null,workspacePayload?.data??workspacePayload??null,workspace);if(!resumeControl.canResume)return res.status(409).json({code:'mission_resume_blocked',error:resumeControl.blockedReason||'A etapa atual não pode ser retomada.',resumeControl});const t=now();db.prepare('UPDATE missions SET status=?,updatedAt=? WHERE id=?').run('running',t,mission.id);db.prepare('UPDATE mission_tasks SET status=?,updatedAt=? WHERE id=?').run('running',t,target.id);emit('mission.resumed',{missionId:mission.id,missionTaskId:target.id,taskId:task.id,resumeFromStage:resumeControl.resumeFromStage},undefined,undefined);emit('mission.task_resumed',{missionId:mission.id,missionTaskId:target.id,taskId:task.id,resumeFromStage:resumeControl.resumeFromStage},undefined,undefined);void runMissionFixed(mission.id);return res.status(202).json({...missionDetail(mission.id),resumeControl});});
