app.get('/api/dashboard',(_,res)=>{const workspaces:any[]=db.prepare('SELECT id,name,type,location,branch,status,updatedAt FROM workspaces ORDER BY updatedAt DESC').all();const rows:any[]=db.prepare(`SELECT t.id,t.workspaceId,t.title,t.pipeline,t.status,t.currentStage,t.lastSuccessfulStage,t.resumable,t.updatedAt,t.createdAt,t.taskBranch,t.environmentStatus,t.environmentWarning,t.environmentErrorCode,w.name AS workspaceName,w.branch AS workspaceBranch FROM tasks t JOIN workspaces w ON w.id=t.workspaceId ORDER BY t.updatedAt DESC`).all();const tasks=rows.map(t=>({...t,pipeline:JSON.parse(t.pipeline),resumable:Boolean(t.resumable)}));const today=new Date().toISOString().slice(0,10);const runningStatuses=new Set(['analyzing','implementing','reviewing','running']);const waitingStatuses=new Set(['approved_waiting_action','needs_manual_review','apply_conflict','failed_preserved']);const attentionStatuses=new Set(['failed','needs_fix','needs_manual_review','apply_conflict','preparation_failed','environment_missing','cleanup_failed','stalled']);const waitingAction=tasks.filter(t=>t.status==='approved'&&t.environmentStatus==='approved_waiting_action'||waitingStatuses.has(t.environmentStatus));const attention=tasks.filter(t=>attentionStatuses.has(t.status)||attentionStatuses.has(t.environmentStatus));const environments=tasks.filter(t=>t.environmentStatus).map(t=>({taskId:t.id,title:t.title,workspaceId:t.workspaceId,workspaceName:t.workspaceName,taskBranch:t.taskBranch,environmentStatus:t.environmentStatus,environmentErrorCode:t.environmentErrorCode,updatedAt:t.updatedAt}));const workspaceSummary=workspaces.map(w=>{const own=tasks.filter(t=>t.workspaceId===w.id);let git:{state:string;branch?:string};try{const info:any=inspectRepository(w.location,w.branch||undefined);git={state:!info.isGitRepository?'unavailable':!info.hasCommits?'no_commit':info.dirty?'dirty':'clean',branch:info.resolvedBaseBranch||info.currentBranch};}catch{git={state:'unavailable'}}return{...w,git,activeTasks:own.filter(t=>runningStatuses.has(t.status)).length,waitingApply:own.filter(t=>t.environmentStatus==='approved_waiting_action').length,preservedEnvironments:own.filter(t=>['failed_preserved','manual_review_preserved','apply_conflict','cleanup_failed'].includes(t.environmentStatus)).length}});const events:any[]=db.prepare('SELECT type,taskId,payload,createdAt FROM events ORDER BY createdAt DESC LIMIT 12').all().map((e:any)=>{let payload:any={};try{payload=JSON.parse(e.payload)}catch{}return{type:e.type,taskId:e.taskId,createdAt:e.createdAt,data:payload.data||payload}});res.json({summary:{running:tasks.filter(t=>runningStatuses.has(t.status)).length,waitingAction:waitingAction.length,attention:attention.length,approvedToday:tasks.filter(t=>t.status==='approved'&&String(t.updatedAt).startsWith(today)).length,preservedEnvironments:environments.filter(e=>['failed_preserved','manual_review_preserved','apply_conflict','cleanup_failed'].includes(e.environmentStatus)).length},runningTasks:tasks.filter(t=>runningStatuses.has(t.status)),waitingActionTasks:waitingAction,attentionTasks:attention,recentTasks:tasks.slice(0,12),workspaces:workspaceSummary,environments,events,providerHealth:[{id:'claude-code',name:'Claude Code',available:process.env.DEVELOPER_PROVIDER==='claude-code'},{id:'codex-cli',name:'Codex CLI',available:process.env.REVIEWER_PROVIDER==='codex-cli'},{id:'prompt-refiner',name:'Prompt Refiner',available:true,model:process.env.PROMPT_REFINER_MODEL||(process.env.PROMPT_REFINER_PROVIDER==='anthropic'?'claude-haiku-4-5-20251001':'mock-fast')},{id:'command-tester',name:'Command Tester',available:true}]})});
