function workspaceUsage(workspaceId:string){const workspace:any=db.prepare('SELECT tokenUsageLimit,enforceTokenUsageLimit FROM workspaces WHERE id=?').get(workspaceId);const executions:any[]=db.prepare('SELECT e.provider,e.tokenUsage,e.estimatedCost,e.taskId FROM executions e JOIN tasks t ON t.id=e.taskId WHERE t.workspaceId=? ORDER BY e.startedAt').all(workspaceId);const normalized=executions.map(e=>({...e,estimatedCost:typeof e.estimatedCost==='number'&&e.estimatedCost>0?e.estimatedCost:undefined}));const total=aggregateUsage(normalized);const limit=Number(workspace?.tokenUsageLimit||0);const enforce=Number(workspace?.enforceTokenUsageLimit||0);const groups=new Map<string,any[]>();for(const execution of normalized){const list=groups.get(execution.provider)||[];list.push(execution);groups.set(execution.provider,list);}return{tokenUsage:total.tokenUsage,estimatedCost:total.estimatedCost??null,costKnown:total.costKnown,taskCount:new Set(executions.map(e=>e.taskId)).size,executionCount:executions.length,tokenUsageLimit:limit,enforceTokenUsageLimit:enforce,usagePercent:limit>0?total.tokenUsage/limit*100:null,byProvider:[...groups].map(([provider,items])=>{const summary=aggregateUsage(items);return{provider,tokenUsage:summary.tokenUsage,estimatedCost:summary.estimatedCost??null,costKnown:summary.costKnown,executionCount:items.length};})};}
