function projectContextResponse(workspace:any){const row:any=db.prepare('SELECT * FROM workspace_contexts WHERE workspaceId=?').get(workspace.id);if(!row)return{version:null,status:'not_analyzed',context:null,analyzedAt:null,sourceCommitSha:null};let context:any=null;try{context=row.contextJson?JSON.parse(row.contextJson):null;}catch{}let status=String(row.status||'not_analyzed');if(status==='ready'&&context?.sourceCommitSha&&workspace.location){const current=inspectRepository(workspace.location,workspace.branch||undefined);if(current.headSha&&current.headSha!==context.sourceCommitSha){status='stale';db.prepare('UPDATE workspace_contexts SET status=?,updatedAt=? WHERE workspaceId=?').run(status,now(),workspace.id);audit('workspace_context.stale_detected',{workspaceId:workspace.id,version:row.version,sourceCommitSha:context.sourceCommitSha});}}return{version:Number(row.version||1),status,context,lastError:row.lastError||null,analyzedAt:row.analyzedAt||context?.analyzedAt||null,sourceCommitSha:row.sourceCommitSha||context?.sourceCommitSha||null};}
