app.post('/api/workspaces/:id/context/analyze',(req,res)=>{const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(req.params.id);if(!workspace)return res.sendStatus(404);const started=Date.now();const t=now();const previous:any=db.prepare('SELECT * FROM workspace_contexts WHERE workspaceId=?').get(workspace.id);db.prepare('INSERT INTO workspace_contexts (workspaceId,version,status,contextJson,lastError,analyzedAt,sourceCommitSha,createdAt,updatedAt) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(workspaceId) DO UPDATE SET version=excluded.version,status=excluded.status,lastError=NULL,updatedAt=excluded.updatedAt').run(workspace.id,1,'analyzing',previous?.contextJson||null,null,previous?.analyzedAt||null,previous?.sourceCommitSha||null,previous?.createdAt||t,t);audit('workspace_context.analysis_started',{workspaceId:workspace.id,version:1});emit('workspace.context.started',{workspaceId:workspace.id,version:1},undefined,undefined);try{const context=analyzeProjectContext(workspace.location,workspace.id,workspace.branch||undefined);const analyzedAt=context.analyzedAt;db.prepare('INSERT INTO workspace_contexts (workspaceId,version,status,contextJson,lastError,analyzedAt,sourceCommitSha,createdAt,updatedAt) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(workspaceId) DO UPDATE SET version=excluded.version,status=excluded.status,contextJson=excluded.contextJson,lastError=NULL,analyzedAt=excluded.analyzedAt,sourceCommitSha=excluded.sourceCommitSha,updatedAt=excluded.updatedAt').run(workspace.id,1,'ready',JSON.stringify(context),null,analyzedAt,context.sourceCommitSha,previous?.createdAt||t,now());const metadata={workspaceId:workspace.id,version:1,sourceCommitSha:context.sourceCommitSha,durationMs:Date.now()-started,detectedLanguages:context.stack.languages,detectedFrameworks:context.stack.frameworks};audit('workspace_context.analysis_completed',metadata);emit('workspace.context.completed',{...metadata},undefined,undefined);res.json({status:'ready',context});}catch(error){const message=error instanceof Error?error.message:String(error);db.prepare('INSERT INTO workspace_contexts (workspaceId,version,status,contextJson,lastError,analyzedAt,sourceCommitSha,createdAt,updatedAt) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(workspaceId) DO UPDATE SET status=excluded.status,lastError=excluded.lastError,updatedAt=excluded.updatedAt').run(workspace.id,1,'failed',previous?.contextJson||null,message,previous?.analyzedAt||null,previous?.sourceCommitSha||null,previous?.createdAt||t,now());audit('workspace_context.analysis_failed',{workspaceId:workspace.id,version:1,durationMs:Date.now()-started,reason:'analysis_failed'});emit('workspace.context.failed',{workspaceId:workspace.id,version:1},undefined,undefined);res.status(500).json({status:'failed',error:'Project context analysis failed'});}});
