function workspaceTokenUsage(workspaceId:string){const row:any=db.prepare("SELECT COALESCE(SUM(COALESCE(e.tokenUsage,0)),0) AS tokens FROM executions e JOIN tasks t ON t.id=e.taskId WHERE t.workspaceId=? AND e.status='completed'").get(workspaceId);return Number(row?.tokens||0);}function assertWorkspaceTokenLimit(workspace:any,taskId:string,stage:string){const limit=Number(workspace?.tokenUsageLimit||0);if(Number(workspace?.enforceTokenUsageLimit||0)!==1||limit<=0)return;const tokenUsage=workspaceTokenUsage(workspace.id);if(tokenUsage>=limit)throw Object.assign(new Error('Workspace token usage limit exceeded'),{kind:'workspace_token_limit_exceeded',workspaceMetadata:{taskId,workspaceId:workspace.id,stage,tokenUsage,tokenUsageLimit:limit}});}
function resumeControlForTask(task:any,budgetExceeded:any,workspaceTokenLimitExceeded:any,workspace:any){const pipeline=JSON.parse(task.pipeline) as any[];const usage:any=db.prepare("SELECT COALESCE(SUM(COALESCE(tokenUsage,0)),0) AS tokens FROM executions WHERE taskId=? AND status='completed'").get(task.id);const limit=Number(workspace?.tokenUsageLimit||0);const workspaceLimitActive=Number(workspace?.enforceTokenUsageLimit||0)===1&&limit>0&&workspaceTokenUsage(task.workspaceId)>=limit;return getResumeControl({pipeline,lastSuccessfulStage:task.lastSuccessfulStage,status:task.status,environmentStatus:task.environmentStatus,resumable:Boolean(task.resumable),budgetExceeded,workspaceTokenLimitExceeded,tokenUsage:Number(usage?.tokens||0),tokenBudget:Number(task.tokenBudget||0),workspaceLimitActive});}
function missionJson(row:any){if(!row)return row;return{...row,assumptions:row.assumptions?JSON.parse(row.assumptions):[],risks:row.risks?JSON.parse(row.risks):[],planVersion:Number(row.planVersion||1)}}
function reconcileMissionApply(mission:any,workspace:any){if(!mission||!workspace||mission.status!=='completed'||!['approved_waiting_action','applied'].includes(mission.environmentStatus||'')||!mission.missionBranch)return;const environment={isolationMode:'worktree' as const,environmentStatus:mission.environmentStatus as any,baseBranch:mission.baseBranch||'',baseCommitSha:mission.baseCommitSha||'',taskBranch:mission.missionBranch,worktreePath:mission.worktreePath,mainDirty:false};if(!isolation.isBranchMerged(environment,workspace.location))return;const cleanup=isolation.cleanupApplied(environment,workspace.location);const warning=cleanup.cleanupComplete?null:'Alterações aplicadas. A limpeza do ambiente está pendente.';db.prepare('UPDATE missions SET environmentStatus=?,environmentWarning=?,missionBranch=?,worktreePath=?,updatedAt=? WHERE id=?').run('applied',warning,cleanup.cleanupComplete?null:mission.missionBranch,cleanup.cleanupComplete?null:mission.worktreePath,now(),mission.id);audit('mission.apply_reconciled',{missionId:mission.id,baseBranch:mission.baseBranch,missionBranch:mission.missionBranch,cleanupComplete:cleanup.cleanupComplete,warning});}
function missionDetail(id:string){let mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(id);if(!mission)return null;const workspaceForRecovery:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);reconcileMissionApply(mission,workspaceForRecovery);mission=db.prepare('SELECT * FROM missions WHERE id=?').get(id);const tasks:any[]=db.prepare('SELECT * FROM mission_tasks WHERE missionId=? ORDER BY position').all(id).map((task:any)=>{const child:any=resolveMissionChildTask(id,task);const execution:any=task.taskId?db.prepare('SELECT role,provider,model,progressMessage,status,error FROM executions WHERE taskId=? ORDER BY startedAt DESC LIMIT 1').get(task.taskId):null;return{...task,acceptanceCriteria:task.acceptanceCriteria?JSON.parse(task.acceptanceCriteria):[],dependsOn:task.dependsOn?JSON.parse(task.dependsOn):[],childTask:child||null,execution:execution?{...execution,error:String(execution.error||'').replace(/(api[_-]?key|token|secret|password)\s*[:=]\s*\S+/gi,'$1:[redacted]').slice(0,500)}:null};});const completed=tasks.filter(task=>task.status==='completed').length;const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);return{mission:missionJson(mission),tasks,progress:{total:tasks.length,completed},workspace,projectContext:{version:mission.projectContextVersion||null,status:mission.projectContextStatus||'not_analyzed',sourceCommitSha:mission.projectContextSourceCommitSha||null}}}
app.post('/api/workspaces/:workspaceId/missions',(req,res)=>{const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(req.params.workspaceId);if(!workspace)return res.sendStatus(404);const title=String(req.body?.title||'').trim(),request=String(req.body?.request||'').trim();if(!title||!request)return res.status(400).json({error:'title e request são obrigatórios'});const id=nanoid(),t=now();db.prepare('INSERT INTO missions (id,workspaceId,title,request,status,planVersion,createdAt,updatedAt) VALUES (?,?,?,?,?,?,?,?)').run(id,workspace.id,title,request,'draft',1,t,t);audit('mission.created',{missionId:id,workspaceId:workspace.id,title});emit('mission.created',{missionId:id,workspaceId:workspace.id,title});res.status(201).json(missionDetail(id));});
app.get('/api/workspaces/:id/missions',(req,res)=>{if(!db.prepare('SELECT id FROM workspaces WHERE id=?').get(req.params.id))return res.sendStatus(404);const rows:any[]=db.prepare('SELECT * FROM missions WHERE workspaceId=? ORDER BY updatedAt DESC').all(req.params.id);res.json(rows.map(row=>{const total:any=db.prepare('SELECT COUNT(*) AS count FROM mission_tasks WHERE missionId=?').get(row.id);const completed:any=db.prepare("SELECT COUNT(*) AS count FROM mission_tasks WHERE missionId=? AND status='completed'").get(row.id);return{...missionJson(row),taskCount:Number(total?.count||0),completedCount:Number(completed?.count||0)}}));});
app.get('/api/missions/:id',(req,res)=>{const detail=missionDetail(req.params.id);if(!detail)return res.sendStatus(404);res.json(detail);});
app.get('/api/missions/:id/diff',(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);if(!workspace)return res.sendStatus(404);try{const environment={isolationMode:'worktree' as const,environmentStatus:mission.environmentStatus||'approved_waiting_action' as const,baseBranch:mission.baseBranch||'',baseCommitSha:mission.baseCommitSha||'',taskBranch:mission.missionBranch,worktreePath:mission.worktreePath,mainDirty:false};return res.json(isolation.diff(environment,workspace.location));}catch(error){return res.status(409).json({error:String(error)});}});
app.post('/api/missions/:id/plan',async(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);if(!['draft','plan_ready','failed'].includes(mission.status))return res.status(409).json({error:'Somente missões em rascunho ou com plano pronto podem ser planejadas.'});const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);const context:any=workspace?projectContextResponse(workspace):null;const plannerConfig=resolveMissionPlannerConfig(mission.workspaceId);db.prepare('UPDATE missions SET status=?,planningError=NULL,updatedAt=?,missionPlannerProvider=?,missionPlannerModel=?,missionPlannerOrigin=? WHERE id=?').run('planning',now(),plannerConfig.provider,plannerConfig.model,plannerConfig.origin,mission.id);audit('mission.planning_started',{missionId:mission.id,workspaceId:mission.workspaceId,provider:plannerConfig.provider,model:plannerConfig.model,origin:plannerConfig.origin});emit('mission.planning_started',{missionId:mission.id,workspaceId:mission.workspaceId});try{const planner=createMissionPlanner(plannerConfig);const plan=await planner.plan({title:mission.title,request:mission.request,workspace:{name:workspace.name,branch:workspace.branch,location:workspace.location},projectContext:context?{version:context.version,status:context.status,sourceCommitSha:context.sourceCommitSha,analyzedAt:context.analyzedAt,context:context.context}:undefined,projectRules:['Preserve existing project conventions','Não executar providers reais']});const error=validateMissionPlan(plan.tasks);if(error)throw new Error(error);const t=now(),insert=db.prepare('INSERT INTO mission_tasks (id,missionId,taskId,position,title,description,acceptanceCriteria,dependsOn,status,createdAt,updatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?)');const ids=plan.tasks.map(()=>nanoid());db.transaction(()=>{db.prepare('DELETE FROM mission_tasks WHERE missionId=?').run(mission.id);plan.tasks.forEach((task:any,index:number)=>insert.run(ids[index],mission.id,null,index,task.title,task.description,JSON.stringify(task.acceptanceCriteria||[]),JSON.stringify((task.dependsOn||[]).map((dependency:number)=>ids[dependency])),'planned',t,t));db.prepare('UPDATE missions SET status=?,planningError=NULL,updatedAt=?,summary=?,assumptions=?,risks=?,projectContextVersion=?,projectContextSourceCommitSha=?,projectContextStatus=? WHERE id=?').run('plan_ready',t,plan.summary,JSON.stringify(plan.assumptions||[]),JSON.stringify(plan.risks||[]),context?.version||null,context?.sourceCommitSha||null,context?.status||'not_analyzed',mission.id)})();audit('mission.plan_ready',{missionId:mission.id,workspaceId:mission.workspaceId,taskCount:plan.tasks.length,provider:plannerConfig.provider,model:plannerConfig.model});emit('mission.plan_ready',{missionId:mission.id,workspaceId:mission.workspaceId,taskCount:plan.tasks.length});res.json(missionDetail(mission.id));}catch(error){const failure=error as any;const safeError=safePlanningError(error);db.prepare('UPDATE missions SET status=?,planningError=?,updatedAt=? WHERE id=?').run('failed',safeError,now(),mission.id);audit('mission.planning_failed',{missionId:mission.id,workspaceId:mission.workspaceId,provider:plannerConfig.provider,model:plannerConfig.model,kind:failure?.kind||'provider_error',format:failure?.format||'structured_json'});return res.status(500).json({error:safeError});}});
app.put('/api/missions/:id/plan',(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);if(!['draft','plan_ready'].includes(mission.status))return res.status(409).json({error:'O plano está congelado após aprovação.'});const input=Array.isArray(req.body?.tasks)?req.body.tasks:[];if(input.length>20)return res.status(400).json({error:'A missão pode ter no máximo 20 etapas.'});const ids=input.map((task:any)=>String(task.id||nanoid()));if(new Set(ids).size!==ids.length)return res.status(400).json({error:'IDs de etapas duplicados.'});const idSet=new Set(ids);for(const task of input){for(const dependency of Array.isArray(task.dependsOn)?task.dependsOn:[]){if(!idSet.has(String(dependency)))return res.status(400).json({error:'Dependência inexistente no plano.'});}}const normalized:MissionPlanTask[]=input.map((task:any)=>({title:String(task.title||'').trim(),description:String(task.description||'').trim(),acceptanceCriteria:Array.isArray(task.acceptanceCriteria)?task.acceptanceCriteria.map(String):[],dependsOn:(Array.isArray(task.dependsOn)?task.dependsOn:[]).map((dependency:any)=>ids.indexOf(String(dependency)))}));const error=validateMissionPlan(normalized);if(error)return res.status(400).json({error});const t=now(),insert=db.prepare('INSERT INTO mission_tasks (id,missionId,taskId,position,title,description,acceptanceCriteria,dependsOn,status,createdAt,updatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?)');db.transaction(()=>{db.prepare('DELETE FROM mission_tasks WHERE missionId=?').run(mission.id);normalized.forEach((task,index)=>insert.run(ids[index],mission.id,null,index,task.title,task.description,JSON.stringify(task.acceptanceCriteria),JSON.stringify(task.dependsOn.map(dependency=>ids[dependency])),'planned',t,t));db.prepare('UPDATE missions SET title=?,request=?,updatedAt=? WHERE id=?').run(typeof req.body?.title==='string'&&req.body.title.trim()?req.body.title.trim():mission.title,typeof req.body?.request==='string'&&req.body.request.trim()?req.body.request.trim():mission.request,t,mission.id)})();audit('mission.plan_updated',{missionId:mission.id,taskCount:normalized.length});emit('mission.plan_updated',{missionId:mission.id,taskCount:normalized.length});res.json(missionDetail(mission.id));});
app.post('/api/missions/:id/approve',(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);if(!['draft','plan_ready'].includes(mission.status))return res.status(409).json({error:'A missão não pode mais ser alterada.'});const rows:any[]=db.prepare('SELECT * FROM mission_tasks WHERE missionId=? ORDER BY position').all(mission.id);if(!rows.length)return res.status(400).json({error:'Não é possível aprovar um plano vazio.'});const ids=new Set(rows.map(row=>row.id));const graph:MissionPlanTask[]=rows.map(row=>({title:row.title,description:row.description,acceptanceCriteria:JSON.parse(row.acceptanceCriteria||'[]'),dependsOn:JSON.parse(row.dependsOn||'[]').map((rowId:string)=>rows.findIndex(item=>item.id===rowId))}));if(rows.some(row=>JSON.parse(row.dependsOn||'[]').some((id:string)=>!ids.has(id))))return res.status(400).json({error:'Dependência inexistente no plano.'});const error=validateMissionPlan(graph);if(error)return res.status(400).json({error});const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);const configs=effectiveConfigs(mission.workspaceId);const policy=effectiveExecutionPolicy(mission.workspaceId);const context=workspace?projectContextResponse(workspace):null;const planner=mission.missionPlannerProvider&&mission.missionPlannerModel?{provider:mission.missionPlannerProvider,model:mission.missionPlannerModel,origin:mission.missionPlannerOrigin||'default'}:resolveMissionPlannerConfig(mission.workspaceId);const t=now();db.prepare('UPDATE missions SET status=?,approvedAt=?,updatedAt=?,plannerProvider=?,plannerModel=?,missionPlannerProvider=?,missionPlannerModel=?,missionPlannerOrigin=?,configSnapshot=?,projectContextSnapshot=?,projectContextVersion=?,projectContextSourceCommitSha=?,projectContextStatus=? WHERE id=?').run('approved',t,t,planner.provider,planner.model,planner.provider,planner.model,planner.origin,JSON.stringify({agents:configs.values,policy:policy.values,missionPlanner:planner}),context?JSON.stringify(context.context||null):null,context?.version||null,context?.sourceCommitSha||null,context?.status||'not_analyzed',mission.id);db.prepare("UPDATE mission_tasks SET status='approved',updatedAt=? WHERE missionId=?").run(t,mission.id);audit('mission.approved',{missionId:mission.id,workspaceId:mission.workspaceId,taskCount:rows.length,provider:planner.provider,model:planner.model});emit('mission.approved',{missionId:mission.id,workspaceId:mission.workspaceId,taskCount:rows.length});res.json(missionDetail(mission.id));});
db.exec("CREATE TRIGGER IF NOT EXISTS mission_task_environment AFTER INSERT ON tasks WHEN NEW.missionId IS NOT NULL BEGIN UPDATE tasks SET isolationMode='worktree',baseBranch=(SELECT baseBranch FROM missions WHERE id=NEW.missionId),baseCommitSha=(SELECT baseCommitSha FROM missions WHERE id=NEW.missionId),taskBranch=(SELECT missionBranch FROM missions WHERE id=NEW.missionId),worktreePath=(SELECT worktreePath FROM missions WHERE id=NEW.missionId),environmentStatus=(SELECT environmentStatus FROM missions WHERE id=NEW.missionId) WHERE id=NEW.id; END;");
app.post('/api/missions/:id/discard',(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);try{if(mission.worktreePath&&mission.missionBranch)isolation.discard({isolationMode:'worktree',environmentStatus:'active',baseBranch:mission.baseBranch||'',baseCommitSha:mission.baseCommitSha||'',taskBranch:mission.missionBranch,worktreePath:mission.worktreePath,mainDirty:false},workspace.location);db.prepare('UPDATE missions SET status=?,environmentStatus=?,updatedAt=? WHERE id=?').run('discarded','discarded',now(),mission.id);emit('mission.discarded',{missionId:mission.id},undefined,undefined);res.json(missionDetail(mission.id));}catch(error){res.status(409).json({error:String(error)})}});
app.post('/api/missions/:id/apply',(req,res)=>{const mission:any=db.prepare('SELECT * FROM missions WHERE id=?').get(req.params.id);if(!mission)return res.sendStatus(404);if(mission.status!=='completed'||!['approved_waiting_action','applied'].includes(mission.environmentStatus||''))return res.status(409).json({error:'A missão precisa estar concluída e aguardando Apply.'});const workspace:any=db.prepare('SELECT * FROM workspaces WHERE id=?').get(mission.workspaceId);if(!workspace)return res.sendStatus(404);try{const environment={isolationMode:'worktree' as const,environmentStatus:mission.environmentStatus||'approved_waiting_action' as const,baseBranch:mission.baseBranch||'',baseCommitSha:mission.baseCommitSha||'',taskBranch:mission.missionBranch,worktreePath:mission.worktreePath,mainDirty:false};const alreadyApplied=mission.environmentStatus==='applied';if(!alreadyApplied){const review=isolation.diff(environment,workspace.location);if(!review.reviewComplete)return res.status(409).json({error:'A revisão das alterações está incompleta. Gere um diff completo antes de aplicar.',code:'mission_diff_incomplete'});}const result=isolation.applyWithRecovery(environment,workspace.location,'orchestrator: prepare mission apply '+mission.id,()=>{db.prepare('UPDATE missions SET environmentStatus=?,environmentWarning=?,updatedAt=? WHERE id=?').run('applied',null,now(),mission.id);});const warning=result.cleanup.cleanupComplete?null:'Alterações aplicadas. A limpeza do ambiente está pendente.';db.prepare('UPDATE missions SET environmentStatus=?,environmentWarning=?,missionBranch=?,worktreePath=?,updatedAt=? WHERE id=?').run('applied',warning,result.cleanup.cleanupComplete?null:mission.missionBranch,result.cleanup.cleanupComplete?null:mission.worktreePath,now(),mission.id);emit('mission.applied',{missionId:mission.id,cleanupComplete:result.cleanup.cleanupComplete,warning},undefined,undefined);return res.json({ok:true,applied:true,cleanupComplete:result.cleanup.cleanupComplete,warning,...missionDetail(mission.id)});}catch(error){return res.status(409).json({error:String(error),code:(error as any)?.code||'apply_conflict'})}});
